from Crypto.Cipher import AES
from Crypto.Util.Padding import pad
def encrypt_record(key, plaintext):
    cipher = AES.new(key, AES.MODE_ECB)
    return cipher.encrypt(pad(plaintext, AES.block_size))

from Crypto.Cipher import AES
from Crypto.Util.Padding import pad
def enc(key, data):
    iv = b"\x00" * AES.block_size
    return AES.new(key, AES.MODE_CBC, iv).encrypt(pad(data, AES.block_size))

from Crypto.Cipher import AES
API_SECRET = "0123456789abcdef0123456789abcdef"
def seal(payload):
    return AES.new(API_SECRET.encode(), AES.MODE_GCM).encrypt(payload)

import requests
def post_payment(card_token):
