import random, string
def reset_token(user):
    alphabet = string.ascii_letters + string.digits
    return "".join(random.choice(alphabet) for _ in range(24))

from Crypto.Cipher import DES
from Crypto.Util.Padding import pad
def legacy_encrypt(key8, data):
    return DES.new(key8, DES.MODE_ECB).encrypt(pad(data, 8))

from Crypto.Cipher import ARC4
def stream(key):
    return ARC4.new(key).encrypt(b"some payload")

def make_api_signature(secret, body):
    import hashlib, hmac
    return hashlib.md5(secret.encode() + body).hexdigest()

def cache_key(rows):
    import hashlib, json
    return hashlib.md5(json.dumps(rows, sort_keys=True).encode()).hexdigest()

def shard(bucket):
    import hashlib
    return int(hashlib.sha1(bucket.encode()).hexdigest(), 16) % 64

